#include <iostream>
#include <cstring>
#include <cctype>
#include <queue>
using namespace std;

const int DIRECTIONS[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};
const int MAXN = 20;
const int MAXNODES = 1000;
const int MAXEDGES = 1000000;

int S, T, total_edges = 1, grid_size, time_limit, INF, head[MAXNODES];
int edge_tail[MAXEDGES], edge_cap[MAXEDGES], edge_next[MAXEDGES];
int sink_nodes[MAXN][MAXN];
int dist[MAXN][MAXN];
int dep_map[MAXN][MAXN];
int node_id[MAXN][MAXN];
char grid_a[MAXN][MAXN];
char grid_b[MAXN][MAXN];
int queue_bfs[MAXNODES * 1000];
int depth_arr[MAXNODES];

void add_edge(int u, int v, int cap) {
    edge_tail[total_edges] = v;
    edge_cap[total_edges] = cap;
    edge_next[total_edges] = head[u];
    head[u] = total_edges++;

    edge_tail[total_edges] = u;
    edge_cap[total_edges] = 0;
    edge_next[total_edges] = head[v];
    head[v] = total_edges++;
}

void bfs_search(int x0, int y0, bool is_build_phase) {
    int l = 0, r = 0;
    queue_bfs[r++] = x0 * 1000 + y0;
    memset(dist, 63, sizeof(dist));
    INF = dist[0][0];
    dist[x0][y0] = 0;

    while (l < r) {
        int x = queue_bfs[l] / 1000;
        int y = queue_bfs[l++] % 1000;

        if (is_build_phase && sink_nodes[x][y] != 0 && dist[x][y] <= time_limit && dist[x][y] <= dep_map[x][y]) {
            add_edge(node_id[x][y], sink_nodes[x][y], INF);
        }

        if (dist[x][y] > time_limit || dist[x][y] >= dep_map[x][y]) continue;

        if (node_id[x][y] == 3 && sink_nodes[x][y] == 9) {
            printf("%d\n", dist[x][y]);
        }

        for (int i = 0; i < 4; i++) {
            int nx = x + DIRECTIONS[i][0];
            int ny = y + DIRECTIONS[i][1];
            if (nx > 0 && nx <= grid_size && ny > 0 && ny <= grid_size && isdigit(grid_a[nx][ny]) && dist[nx][ny] == INF) {
                dist[nx][ny] = dist[x][y] + 1;
                queue_bfs[r++] = nx * 1000 + ny;
            }
        }
    }
}

bool level_graph_build() {
    memset(depth_arr, 0, sizeof(depth_arr));
    int l = 0, r = 0;
    queue_bfs[r++] = S;
    depth_arr[S] = 1;

    while (l < r) {
        int u = queue_bfs[l++];
        for (int e = head[u]; e; e = edge_next[e]) {
            int v = edge_tail[e];
            if (depth_arr[v] || !edge_cap[e]) continue;
            depth_arr[v] = depth_arr[u] + 1;
            queue_bfs[r++] = v;
            if (v == T) return true;
        }
    }
    return false;
}

int dfs_flow(int u, int flow) {
    if (u == T) return flow;
    int pushed = 0;
    for (int e = head[u]; e && flow - pushed; e = edge_next[e]) {
        int v = edge_tail[e];
        if (depth_arr[v] != depth_arr[u] + 1 || !edge_cap[e]) continue;
        int f = dfs_flow(v, min(flow - pushed, edge_cap[e]));
        pushed += f;
        edge_cap[e] -= f;
        edge_cap[e ^ 1] += f;
    }
    if (pushed == 0) depth_arr[u] = -1;
    return pushed;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    cin >> grid_size >> time_limit;

    for (int i = 1; i <= grid_size; i++) {
        cin >> grid_a[i] + 1;
    }

    for (int i = 1; i <= grid_size; i++) {
        cin >> grid_b[i] + 1;
    }

    memset(dep_map, 63, sizeof(dep_map));
    for (int i = 1; i <= grid_size; i++) {
        for (int j = 1; j <= grid_size; j++) {
            if (grid_a[i][j] == 'Z') {
                bfs_search(i, j, false);
            }
        }
    }
    memcpy(dep_map, dist, sizeof(dist));

    int node_count = 1;
    S = 0;
    T = 1;

    for (int i = 1; i <= grid_size; i++) {
        for (int j = 1; j <= grid_size; j++) {
            if (grid_a[i][j] > '0' && grid_a[i][j] <= '9') {
                node_id[i][j] = ++node_count;
                add_edge(S, node_id[i][j], grid_a[i][j] - '0');
            }
            if (grid_b[i][j] > '0' && grid_b[i][j] <= '9') {
                sink_nodes[i][j] = ++node_count;
                add_edge(sink_nodes[i][j], T, grid_b[i][j] - '0');
            }
        }
    }

    for (int i = 1; i <= grid_size; i++) {
        for (int j = 1; j <= grid_size; j++) {
            if (node_id[i][j]) {
                bfs_search(i, j, true);
            }
        }
    }

    int max_flow = 0;
    while (level_graph_build()) {
        max_flow += dfs_flow(S, INF);
    }

    cout << max_flow << "\n";
    return 0;
}
